import{dg}from"./buffer-277.js";let recordStats=()=>{if(dg.value!=null){dg.value=null;dg.addProjectionMetrics=null;throw new Error("Stats are already being measured")}let b={layoutProjection:{nodes:[],calculatedTargetDeltas:[],calculatedProjections:[]}};dg.value=b;dg.addProjectionMetrics=a=>{b.layoutProjection.nodes.push(a.nodes);b.layoutProjection.calculatedTargetDeltas.push(a.calculatedTargetDeltas);b.layoutProjection.calculatedProjections.push(a.calculatedProjections)}};export{recordStats};